-- NavVis VLX 3 + IVION seed for Turso SQL Editor
-- IMPORTANT: Run Step 1, then Step 2 separately (do not rely on DELETE).

-- Step 0 (optional): create tables if they do not exist yet
CREATE TABLE IF NOT EXISTS training_modules (
  id TEXT PRIMARY KEY NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  summary TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL DEFAULT 'module',
  duration_minutes INTEGER NOT NULL DEFAULT 15,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_published INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS training_tests (
  id TEXT PRIMARY KEY NOT NULL,
  module_id TEXT NOT NULL,
  title TEXT NOT NULL,
  passing_score INTEGER NOT NULL DEFAULT 80,
  questions_json TEXT NOT NULL DEFAULT '[]',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);


-- Step 1: run this by itself first
INSERT INTO training_modules (
  id, slug, title, summary, body, kind, duration_minutes, sort_order, is_published, created_at, updated_at
) VALUES (
  'tm_navvis_vlx3_ivion',
  'navvis-vlx3-ivion',
  'NavVis VLX 3 with IVION for Construction',
  'Interactive field-to-cloud training for the NavVis VLX 3 wearable scanner and NavVis IVION — capture, control points, IVION Processing, sites, measurement, and construction collaboration.',
  '{"version":1,"interactive":true,"chapters":[{"id":"meet-vlx3","eyebrow":"Chapter 1 · Know the kit","title":"Meet the NavVis VLX 3","blocks":[{"type":"text","markdown":"## Wearable survey-grade reality capture\n\nThe **NavVis VLX 3** is a wearable mobile mapping system built for large, complex indoor and outdoor sites. Operators walk the space while dual LiDAR sensors and panoramic cameras capture dense point clouds and 360° imagery.\n\nPaired with **NavVis IVION**, that capture becomes a shared browser-based site — walkthroughs, measurements, model checks, and stakeholder access without specialized desktop viewers."},{"type":"video","title":"Meet NavVis VLX 3","youtubeId":"04Du4SAvYFU","caption":"Official NavVis introduction — dual 32-layer LiDAR, panoramic cameras, and live scanning feedback.","sourceLabel":"Watch on YouTube (NavVis)","sourceUrl":"https://www.youtube.com/watch?v=04Du4SAvYFU"},{"type":"callout","tone":"tip","title":"Platform basics","body":"2 × 32-layer LiDAR (~1.28M pts/s each), 4 × 20 MP panoramic cameras, ~8.5 kg with batteries, IP42, 1 TB portable SSD, ~1.5 h per battery set (hot-swappable), local point cloud accuracy about 5 mm in NavVis test conditions."},{"type":"checklist","title":"What the VLX 3 is built to do","items":["Capture large campuses, factories, and multi-floor buildings quickly","Produce dense point clouds plus operator-free 360° panoramas","Support ground and wall control points for geo-registration","Feed NavVis IVION for processing, hosting, and collaboration","Export standard formats (E57, LAS, PTS, XYZ, PLY, RCS, and more)"]},{"type":"resource","title":"NavVis VLX 3 product page","url":"https://www.navvis.com/vlx-3","description":"Official VLX 3 overview, capabilities, and downloadable product materials."},{"type":"quiz","id":"q-meet-form","prompt":"What form factor is the NavVis VLX 3?","choices":["Tripod-only terrestrial laser scanner","Wearable mobile mapping system","Phone clip-on depth camera","Drone-only aerial LiDAR pod"],"correctIndex":1,"explanation":"VLX 3 is worn by the operator so they can walk complex sites while capturing LiDAR and panoramas."},{"type":"minigame","kind":"match","id":"game-meet-match","title":"Match the NavVis toolkit","prompt":"Pair each piece with its role.","pairs":[{"term":"VLX 3","definition":"Wearable scanner for field capture"},{"term":"IVION Processing","definition":"Cloud processing of point clouds and panoramas"},{"term":"NavVis IVION","definition":"Browser platform for sites, measure, and share"},{"term":"Control points","definition":"Surveyed anchors for geo-registration"}],"success":"Toolkit mapped — capture on VLX 3, live the site in IVION."}]},{"id":"construction-use-cases","eyebrow":"Chapter 2 · Why it matters on site","title":"Construction and AEC use cases","blocks":[{"type":"text","markdown":"## When VLX 3 + IVION earn their keep\n\nUse this stack when teams need **complete as-is coverage** across large floors, plants, or campuses — and stakeholders need to **walk, measure, and verify** without flying to site.\n\nTypical wins: progress documentation, scan-to-BIM inputs, construction verification, clash context, and facility handover digital twins."},{"type":"checklist","title":"High-value missions","items":["Multi-floor commercial interiors and mechanical spaces","Factories / process plants with dense MEP","Campus and mixed indoor/outdoor documentation","As-built capture for BIM modeling and validation","Remote owner / GC walkthroughs via IVION links","Measurement and issue context without another site trip"]},{"type":"callout","tone":"warn","title":"Right tool check","body":"VLX 3 is a production mobile mapper. If the job only needs a quick photoreal walkthrough with no survey-grade cloud, a lighter visualization camera may be enough — but do not expect VLX-class measured coverage from a phone."},{"type":"scenario","title":"Jobsite scenario: plant shutdown window","situation":"You have a short outage window to document a dense mechanical room for BIM coordination. Remote engineers need to measure clearances tomorrow. What’s the plan?","choices":[{"label":"Shoot a few phone panoramas and email them","feedback":"Too thin for measured coordination across a dense room."},{"label":"Walk the VLX 3 through the space, process in IVION, and share a site with Mark & Measure access","feedback":"Correct — complete capture plus browser measurement for remote engineers.","correct":true},{"label":"Wait for a full TLS setup on every corner after the outage ends","feedback":"TLS has a place, but the outage window favors fast wearable coverage first."}]},{"type":"minigame","kind":"rapid","id":"game-construction-rapid","title":"Use-case speed round","prompt":"True or false for VLX 3 + IVION construction work.","passScore":3,"rounds":[{"statement":"IVION lets stakeholders explore and measure scanned spaces in a browser.","correct":true,"explanation":"That shared access is a core collaboration win."},{"statement":"VLX 3 panoramas are captured so the operator typically appears in every image.","correct":false,"explanation":"Cameras are positioned so the operator stays out of the panoramic field of view."},{"statement":"Control points help lock datasets into a local or global coordinate system.","correct":true,"explanation":"Ground and wall control support geo-registration."},{"statement":"IVION is only useful for marketing screenshots, not construction verification.","correct":false,"explanation":"IVION supports measurement, model validation, and remote site assessment."}],"success":"Solid judgment — you know when this stack fits the job."}]},{"id":"field-kit","eyebrow":"Chapter 3 · Field capture","title":"Suit up and scan with VLX 3","blocks":[{"type":"text","markdown":"## Wearable workflow basics\n\nFit the harness, mount charged batteries, confirm storage, and use the onboard touch display for **live scanning feedback** — coverage and SLAM status while you walk.\n\nPlan loops that revisit distinctive geometry. Watch for tight doors, stairs, and overhead hazards — the system is powerful, but the operator still owns site safety."},{"type":"callout","tone":"tip","title":"Battery reality","body":"Expect about 1.5 hours per set of two batteries. Four batteries ship so you can hot-swap and keep scanning. Charge in the office; don’t discover empty packs at the gate."},{"type":"checklist","title":"Preflight checklist","items":["Harness fit and device secure before walking","Two charged batteries seated; spares ready","1 TB SSD available and mounted","Project / dataset naming matches the construction document system","Control point plan ready if absolute alignment is in scope","Route sketch for floors, stairs, and outdoor links"]},{"type":"resource","title":"NavVis VLX 3 specifications","url":"https://knowledge.navvis.com/docs/navvis-vlx-3-specifications","description":"Official hardware, accuracy, battery, and output specifications."},{"type":"quiz","id":"q-field-feedback","prompt":"Why does live scanning feedback on the VLX 3 display matter?","choices":["It only shows the weather forecast","It helps you catch coverage gaps and SLAM issues while you can still fix them","It replaces the need for any control points forever","It automatically drafts the BIM model on device"],"correctIndex":1,"explanation":"Real-time coverage and SLAM status let you correct problems in the field instead of discovering holes later."},{"type":"minigame","kind":"order","id":"game-field-order","title":"Order the field start","prompt":"Put these VLX 3 start steps in a sensible order.","items":["Begin the planned walking route while watching live feedback","Confirm batteries, storage, and dataset naming","Fit and secure the wearable system","End the dataset cleanly and prepare offload / upload"],"correctOrder":[2,1,0,3],"success":"Suit up → confirm → walk with feedback → close cleanly."}]},{"id":"control-points","eyebrow":"Chapter 4 · Coordinates that stick","title":"Control points and geo-registration","blocks":[{"type":"text","markdown":"## Survey control is part of the capture plan\n\nVLX 3 supports **ground and wall control points** so datasets can lock into local site coordinates or national/global systems.\n\nControl measured with total stations or GNSS rovers can be captured during the mapping workflow. Absolute accuracy depends on environment size and control discipline — plan control before you walk, not after stakeholders ask for coordinates."},{"type":"callout","tone":"warn","title":"Process-time verification","body":"In IVION Processing, upload a geo-referenced control point file and verify control on the quality map before you commit processing. Catch bad control early."},{"type":"scenario","title":"Jobsite scenario: two buildings, one coordinate system","situation":"Building A was scanned Monday and Building B Wednesday. The GC needs both in the same site coordinate system for overlay. What should have been true?","choices":[{"label":"Hope the SLAM drifts match by coincidence","feedback":"Hope is not a coordinate system."},{"label":"Capture both datasets against the same control network / coordinate strategy","feedback":"Yes — shared control and consistent registration strategy keep campuses alignable.","correct":true},{"label":"Delete Building A and rescan everything as one continuous walk only","feedback":"Sometimes helpful, but not required if control and alignment workflows are solid."}]},{"type":"quiz","id":"q-control-support","prompt":"Which control point types does VLX 3 support?","choices":["Ground only","Wall only","Ground and wall","Ceiling stickers exclusively"],"correctIndex":2,"explanation":"NavVis documents ground and wall control point support for geo-registration."},{"type":"minigame","kind":"match","id":"game-control-match","title":"Match the control idea","prompt":"Pair each term with the right meaning.","pairs":[{"term":"Local accuracy","definition":"Point cloud consistency in a local region (~5 mm class in NavVis tests)"},{"term":"Control points","definition":"Surveyed anchors used to geo-register datasets"},{"term":"Quality map","definition":"Place to verify control before processing commits"},{"term":"Dataset alignment","definition":"Bringing multiple datasets into one site frame"}],"success":"Control language locked — plan it before the walk."}]},{"id":"ivion-processing","eyebrow":"Chapter 5 · Cloud processing","title":"NavVis IVION Processing","blocks":[{"type":"text","markdown":"## From SSD to actionable cloud\n\n**NavVis IVION Processing** turns VLX datasets into processed point clouds and panoramas in the cloud. You can start processing once scans are uploaded — including from the field when connectivity allows.\n\nConfigure point cloud and panorama settings, process datasets in parallel, monitor progress, and push results into site dataset management."},{"type":"video","title":"NavVis IVION Processing overview","youtubeId":"n2X07dWUFMA","caption":"Official NavVis short on secure, parallel cloud processing for point clouds and panoramas.","sourceLabel":"Watch on YouTube (NavVis)","sourceUrl":"https://www.youtube.com/watch?v=n2X07dWUFMA"},{"type":"checklist","title":"Processing workflow habits","items":["Work from the published site version to access Data processing","Upload unprocessed datasets (drag/drop or file picker)","Create a processing task with the right quality / environment settings","Verify control points on the quality map when used","Add processed data to Dataset Management for site setup","Keep naming consistent: Building-Level-Zone-Date"]},{"type":"callout","tone":"tip","title":"Draft vs published","body":"Data processing lives on the published version of the site. If you’re stuck in draft, exit draft to upload and process."},{"type":"resource","title":"NavVis IVION Processing","url":"https://www.navvis.com/ivion/data-processing","description":"Cloud processing overview: parallel tasks, control verification, and outputs."},{"type":"quiz","id":"q-processing-where","prompt":"Where do you upload unprocessed VLX data for IVION Processing?","choices":["Only from a Revit plugin","Data processing on the published IVION site","A random USB stick left in a pickup","Social media DMs"],"correctIndex":1,"explanation":"Upload and process from the Data processing area on the published site version."},{"type":"minigame","kind":"order","id":"game-processing-order","title":"Order the processing flow","prompt":"Put the IVION Processing steps in order.","items":["Add processed data to Dataset Management / site setup","Create and run a processing task","Upload unprocessed datasets","Verify control / review quality outputs as needed"],"correctOrder":[2,1,3,0],"success":"Upload → process → verify → manage on the site."}]},{"id":"ivion-sites","eyebrow":"Chapter 6 · Live the site","title":"IVION sites, walkthroughs, and measurement","blocks":[{"type":"text","markdown":"## Browser digital twin for the whole team\n\n**NavVis IVION** hosts aligned datasets as navigable sites. Stakeholders walk panoramic paths, inspect point clouds, and use tools like **Mark & Measure** without installing a heavy viewer.\n\nSites organize access and locations. Global admins create sites; teams collaborate in draft vs published workflows for controlled updates."},{"type":"checklist","title":"What teams do in IVION","items":["Navigate as-is conditions remotely","Take point-to-point measurements in 2D/3D views","Compare design models against scanned reality","Tag assets / issues for facility and construction follow-up","Share access with owners, trades, and remote PMs","Export or integrate with BIM / FM tools as licensed"]},{"type":"scenario","title":"Jobsite scenario: RFI with distance","situation":"An MEP trade disputes a clearance. The GC needs a defendable measurement from last week’s scan without flying back. What’s best?","choices":[{"label":"Guess from a phone photo attachment","feedback":"Not defendable when millimeters matter."},{"label":"Open the IVION site, navigate to the location, and measure with Mark & Measure","feedback":"Correct — shared scanned reality with a measured answer.","correct":true},{"label":"Ask everyone to remember the dimension from the toolbox talk","feedback":"Culture is nice; coordinates are better."}]},{"type":"resource","title":"NavVis IVION platform","url":"https://www.navvis.com/ivion","description":"Official IVION overview: collaboration, verification, and site access."},{"type":"quiz","id":"q-ivion-measure","prompt":"Which IVION capability helps take point-to-point distances in the browser?","choices":["Mark & Measure","Battery hot-swap","Harness sizing chart","Tripod bubble level only"],"correctIndex":0,"explanation":"Mark & Measure is the IVION toolset for precise measurements in site views."}]},{"id":"deliverables","eyebrow":"Chapter 7 · Make it useful","title":"Alignment, exports, and construction handoff","blocks":[{"type":"text","markdown":"## From datasets to decisions\n\nAfter processing, align datasets in site setup (manual and control-point-based automatic alignment). Publish a clean site experience for non-specialists.\n\nWhen downstream tools need files, export standard point cloud formats and keep a clear naming / version trail so BIM and survey teams trust the handoff."},{"type":"callout","tone":"fun","title":"Pro move","body":"Name like a construction document: Campus-Building-Level-YYYYMMDD-Seg##. Future alignment-you and BIM-you will high-five present-you."},{"type":"checklist","title":"Done looks like this","items":["Processed datasets aligned into one coherent site","Published IVION access for the right stakeholders","Key measurements / issues documented where needed","Exports delivered in the formats the contract actually names","Raw and processed storage paths documented for the project"]},{"type":"quiz","id":"q-alignment","prompt":"After IVION Processing, how do multiple datasets typically become one navigable site?","choices":["They auto-merge in the battery charger","Through Dataset Alignment / site setup in NavVis IVION","By renaming files to the same name","Alignment is impossible with VLX 3 data"],"correctIndex":1,"explanation":"Processed datasets are aligned in NavVis IVION site setup (manual or control-based)."},{"type":"minigame","kind":"rapid","id":"game-deliverables-rapid","title":"Handoff speed round","prompt":"True or false for construction handoff.","passScore":3,"rounds":[{"statement":"A raw SSD folder with no IVION site is usually enough for remote owners.","correct":false,"explanation":"Stakeholders need accessible walkthroughs and tools."},{"statement":"VLX 3 can export common point cloud formats used by survey and BIM workflows.","correct":true,"explanation":"E57, LAS, and related formats are part of the ecosystem."},{"statement":"Consistent naming helps multi-day campus programs stay alignable.","correct":true,"explanation":"Chaos in names becomes chaos in alignment."},{"statement":"Only the scanner operator should ever open IVION.","correct":false,"explanation":"IVION is designed so broader teams can explore and act on site data."}],"success":"Handoff mindset locked — capture is only half the job."}]},{"id":"debrief","eyebrow":"Chapter 8 · Mission debrief","title":"You’re ready for the certification test","blocks":[{"type":"text","markdown":"## Field → IVION → handoff\n\nYou can explain what VLX 3 captures, run a disciplined wearable session, use control thoughtfully, process in IVION, and deliver a site people can actually use.\n\nNext: pass the certification test (80%) and earn the medal."},{"type":"checklist","title":"Pre-test self check","items":["I know VLX 3 is a wearable dual-LiDAR mapper with panoramic cameras","I can describe IVION Processing vs the IVION site experience","I plan control points when absolute alignment matters","I use live feedback to catch coverage/SLAM issues in the field","I can point stakeholders to Mark & Measure for browser distances","I treat naming, alignment, and access as part of the deliverable"]},{"type":"minigame","kind":"baton","id":"game-debrief-timing","title":"Steady operator timing","prompt":"Tap in the window — smooth operators beat rushed operators.","success":"Steady timing. Take the certification when you’re ready."},{"type":"quiz","id":"q-debrief-pass","prompt":"Passing score for the VLX 3 + IVION certification test is:","choices":["50%","65%","80%","100% only"],"correctIndex":2,"explanation":"You need 80% or better to earn the certification medal."},{"type":"callout","tone":"fun","title":"See you on the medal stand","body":"Open the certification test when you’re ready. Complete sites beat incomplete hero scans."}]}]}',
